#include "ark/agent.hpp"
#include "ark/serialize.hpp"
#include "ark/history_authoring.hpp"
#include <iostream>
#include <stdexcept>
#include <cmath>
using namespace ark;using V=arkjson::Value;
static int checks=0;
static void check(bool ok,const std::string& why){++checks;if(!ok)throw std::runtime_error(why);}
static V json(const std::string& s){V v;check(arkjson::parse(s,v),"Invalid fixture JSON");return v;}
static const V& at(const V& v,const char* key){static V empty;const auto* p=v.find(key);return p?*p:empty;}
static V invoke(AgentSession& s,const char* name,V args){if(!args.find("expected_revision"))args.set("expected_revision",V::makeNum((double)s.revision));const V r=s.call(name,args);check(!at(r,"isError").b,r.dump());return at(r,"structuredContent");}
static V fixture(){V commands=V::makeArr();for(int surface=0;surface<2;++surface){V command=json(R"({"op":"feature.add","type":"bspline_surface","p":{"u_degree":3,"v_degree":3}})"),native=V::makeObj(),poles=V::makeArr();for(int u=0;u<4;++u){V row=V::makeArr();for(int v=0;v<4;++v){V point=V::makeArr();const double z[]={0,0,6,18};point.arr={V::makeNum(surface?-10*u:5+10*u),V::makeNum(10*v),V::makeNum(surface?z[u]:2+u)};row.arr.push_back(point);}poles.arr.push_back(row);}native.set("poles",poles);command.set("native",native);command.set("name",V::makeStr(surface?"Target":"Source"));commands.arr.push_back(command);}V a=V::makeObj();a.set("commands",commands);return a;}
int main(){try{
    AgentSession s;s.suppressFailureCapture();s.suppressIterationHistory();invoke(s,"doc_apply",fixture());const auto original=documentToJson(s.document);V quality=json(R"({"action":"quality","id":2,"samples":9})");const auto sampled=invoke(s,"surface_control",quality);check(at(sampled,"display_grid_cells_safe").b,"Complete UV rectangle should permit display cells");check(at(sampled,"valid_samples").num==81,"Native curvature grid should have 81 regular samples");check(std::abs(at(at(sampled,"samples").arr.front(),"min_curvature_per_mm").num+.04)<1e-9,"Analytic parabolic-cylinder boundary curvature");check(std::abs(at(at(sampled,"samples").arr.front(),"max_curvature_per_mm").num)<1e-9,"Cylinder second principal curvature must be zero");check(documentToJson(s.document)==original,"Quality read changed authored source");
    const auto source=invoke(s,"surface_control",json(R"({"action":"inspect","id":1})"));const auto target=invoke(s,"surface_control",json(R"({"action":"inspect","id":2})"));V request=json(R"({"action":"match_plan","id":1,"target_id":2,"source_side":"u_min","target_side":"u_min","continuity":2,"max_displacement_mm":20,"samples":33,"name":"G2 transition"})");request.set("source_brep_sha256",at(source,"source_brep_sha256"));request.set("target_brep_sha256",at(target,"source_brep_sha256"));
    auto rejected=[&](V a){a.set("expected_revision",V::makeNum((double)s.revision));const auto before=documentToJson(s.document);check(at(s.call("surface_control",a),"isError").b,"Invalid matching request accepted");check(documentToJson(s.document)==before,"Rejected match modified source");};
    V bad=request;bad.set("source_brep_sha256",V::makeStr("stale"));rejected(bad);bad=request;bad.set("target_brep_sha256",V::makeStr("stale"));rejected(bad);bad=request;bad.set("max_displacement_mm",V::makeNum(.1));rejected(bad);bad=request;bad.set("source_side",V::makeStr("mesh_edge_0"));rejected(bad);bad=request;bad.set("tolerance",V::makeNum(.1));rejected(bad);
    const auto plan=invoke(s,"surface_control",request);check(documentToJson(s.document)==original,"Match plan changed source");const auto& evidence=at(plan,"evidence");check(at(at(evidence,"after"),"sampled_g2").b,"Native D2 tensor must verify G2");check(!at(evidence,"global_continuity_verified").b,"Sampled evidence claimed global continuity");check(at(evidence,"opposite_boundary_preserved").b,"Opposite boundary not preserved");check(at(at(evidence,"before"),"max_gap_mm").num>5,"Fixture must start with actual gap");
    const auto preview=invoke(s,"doc_preview",at(at(plan,"preview"),"arguments"));V apply=V::makeObj();apply.set("candidate_id",at(preview,"candidate_id"));invoke(s,"doc_apply",apply);const u64 matched=s.document.features.back().id;check(matched==3,"One matched feature expected");check(!consumedFeatureInputs(s.document).count(2),"Matching consumed its target support");
    V inspect=json(R"({"action":"inspect"})");inspect.set("id",V::makeNum((double)matched));const auto net=invoke(s,"surface_control",inspect);const auto& poles=at(net,"poles").arr;check(std::abs(at(poles[0],"point_mm").arr[0].num)<1e-9&&std::abs(at(poles[0],"point_mm").arr[2].num)<1e-9,"Boundary pole position");check(std::abs(at(poles[4],"point_mm").arr[0].num-10)<1e-9&&std::abs(at(poles[4],"point_mm").arr[2].num)<1e-9,"G1 interior pole row");check(std::abs(at(poles[8],"point_mm").arr[0].num-20)<1e-9&&std::abs(at(poles[8],"point_mm").arr[2].num-6)<1e-9,"G2 second interior row");check(at(poles[12],"point_mm").arr[0].num==35&&at(poles[12],"point_mm").arr[2].num==5,"Opposite boundary changed");
    auto seam=json(R"({"action":"seam","id":3,"target_id":2,"source_side":"u_min","target_side":"u_min","samples":65})");const auto checked=invoke(s,"surface_control",seam);check(at(checked,"sampled_g2").b&&at(checked,"max_gap_mm").num<1e-8&&at(checked,"max_curvature_tensor_error_per_mm").num<1e-8,"Independent seam readback failed");
    Document restored;std::string error;check(documentFromJson(documentToJson(s.document),restored,&error),error);restored.recompute();for(const auto& r:restored.lastResults)check(r.ok,r.error);check(restored.features.back().nativeSpec.find("op")->str=="match_boundary","Persisted recipe missing");
    AgentSession g0;g0.suppressIterationHistory();invoke(g0,"doc_apply",fixture());V p0=request;p0.set("continuity",V::makeNum(0));const auto zero=invoke(g0,"surface_control",p0);check(at(at(at(zero,"evidence"),"after"),"sampled_g0").b&&!at(at(at(zero,"evidence"),"after"),"sampled_g1").b,"G0 must not be promoted to G1");p0.set("continuity",V::makeNum(1));const auto one=invoke(g0,"surface_control",p0);check(at(at(at(one,"evidence"),"after"),"sampled_g1").b&&!at(at(at(one,"evidence"),"after"),"sampled_g2").b,"G1 must not be promoted to G2");
    V rationalNative=g0.document.find(2)->nativeSpec,weights=V::makeArr();for(int u=0;u<4;++u){V row=V::makeArr();for(int v=0;v<4;++v)row.arr.push_back(V::makeNum(u==1&&v==1?1.2:1.));weights.arr.push_back(row);}rationalNative.set("weights",weights);V edit=json(R"({"commands":[{"op":"feature.edit","id":2}]})");auto editedCommands=at(edit,"commands");editedCommands.arr.front().set("native",rationalNative);edit.set("commands",editedCommands);invoke(g0,"doc_apply",edit);auto rationalInfo=invoke(g0,"surface_control",json(R"({"action":"inspect","id":2})"));V rational=request;rational.set("expected_revision",V::makeNum((double)g0.revision));rational.set("target_brep_sha256",at(rationalInfo,"source_brep_sha256"));const auto rationalBefore=documentToJson(g0.document),rationalResult=g0.call("surface_control",rational).dump();check(rationalResult.find("non-rational")!=std::string::npos,"Rational matching must reject rather than approximate weights");check(documentToJson(g0.document)==rationalBefore,"Rational rejection altered source");
    AgentSession disk;disk.suppressIterationHistory();invoke(disk,"doc_apply",json(R"({"commands":[{"op":"sketch.set","name":"Disk boundary","sketch":{"plane":"XY","entities":[{"kind":"circle","name":"rim","dof":[0,0,10]}]}},{"op":"feature.add","name":"Trimmed disk","type":"surface_fill","p":{"sketch":"Disk boundary"}}]})"));const auto circle=invoke(disk,"surface_control",json(R"({"action":"quality","id":1,"samples":17})"));check(!at(circle,"display_grid_cells_safe").b&&at(circle,"outside_trim_samples").num>0,"Nonrectangular face must not display interpolated cells across trims");check(std::abs(at(circle,"max_abs_curvature_per_mm").num)<1e-10,"Native planar disk curvature");
    auto stale=quality;stale.set("expected_revision",V::makeNum(0));check(at(s.call("surface_control",stale),"isError").b,"Stale quality query accepted");auto badSamples=quality;badSamples.set("samples",V::makeNum(100));rejected(badSamples);
    std::cout<<checks<<" surface quality/matching checks passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
